-- =============================================================================
-- SICAPDA by FLUXE — DADOS DE EXEMPLO (para desenvolvimento e demonstração)
-- =============================================================================
-- Como usar (depois de importar config/database.sql):
--   mysql -u root controle_acesso < config/dados_exemplo.sql
--   (ou, no phpMyAdmin: selecione o banco "controle_acesso" > Importar > este arquivo)
--
-- O que cria: 1 empresa de demonstração, 1 usuário administrador, 20 funcionários
-- com credenciais (RFID, biometria e código), 3 catracas/leitores, metas de refeições
-- e ~30 dias de acessos e de produção de refeições (as datas são sempre relativas
-- a HOJE, só em dias úteis, então os gráficos e o painel aparecem preenchidos).
--
-- LOGIN DE DEMONSTRAÇÃO
--     e-mail: demo@fluxe.com        senha: Fluxe@123
--
-- Pode rodar de novo quando quiser: o script apaga a empresa de demonstração
-- (e tudo que pertence a ela) antes de recriar. NÃO mexe em outras empresas.
-- ATENÇÃO: é só para teste. Não use essa senha nem esses dados em produção.
-- Todos os nomes, CPFs, CNPJ e telefones abaixo são FICTÍCIOS.
-- =============================================================================
USE controle_acesso;

SET NAMES utf8mb4;

-- ─── Limpa a demonstração anterior (se existir) ──────────────────────────────
DELETE FROM usuarios WHERE email = 'demo@fluxe.com';
DELETE FROM empresas WHERE cnpj = '11222333000181';   -- apaga em cascata funcionários, logs etc.

-- ─── Empresa ─────────────────────────────────────────────────────────────────
     endereco, cep, cidade, estado, telefone, site, horario_funcionamento,
     responsavel_contrato, email_institucional, possui_refeitorio, controle_atual_refeicoes,
     recursos_acesso, integracoes, criado_em)
VALUES
    ('Alimentos Modelo Indústria e Comércio LTDA', 'Alimentos Modelo', '11222333000181', '123456789110',
     'Indústria', 20,
     'Av. das Indústrias, 1500', '13730000', 'Mococa', 'SP', '(19) 3600-0000', 'https://www.exemplo.com.br',
     '06:00 - 18:00',
     'Maria Helena Duarte', 'contato@exemplo.com.br', 1, 'Planilha',
     '["rfid", "biometria", "codigo"]', '["ERP", "Folha de pagamento"]', NOW());
SET @emp = LAST_INSERT_ID();

-- ─── Usuário administrador (senha: Fluxe@123, gravada com bcrypt) ─────────────
     dois_fatores_habilitado, dois_fatores_metodo, empresa_id, criado_em)
VALUES
    ('Administrador Demo', '11144477735', '(19) 99999-0000', 'Gestor de Operações', 'ADM-001', NULL,
     'demo@fluxe.com', '$2y$10$PZ86DE77HM4Ja7uUdgZ2KenghmaQd6kgz9mKsq9.yQv4ePLhHfOCS', 'admin', 0, NULL, @emp, NOW());

-- ─── Metas de refeições por dia (aparecem em Configurações/Previsão) ─────────


-- ─── Funcionários (20: 10 operadores, 4 supervisores, 5 prestadores, 1 inativo) ─
SET @f1 = LAST_INSERT_ID();   -- id do 1º funcionário; os demais são @f1 + 1, @f1 + 2, ...

-- ─── Dispositivos (catracas / leitores). O "token" é o que o aparelho envia ao sistema ─
SET @d1 = LAST_INSERT_ID();   -- id da 1ª catraca; as demais são @d1 + 1 e @d1 + 2

-- ─── Credenciais de acesso (cartão RFID para todos; biometria e código para alguns) ─
SET @c1 = LAST_INSERT_ID();   -- id da 1ª credencial (a RFID do funcionário 0); as RFID seguem @c1 + índice do funcionário

-- ─── Logs de acesso: ~30 dias de entradas e saídas (dias úteis) + algumas tentativas negadas ─
-- Hoje (se for dia útil): quem já "chegou" aparece em "presentes agora" na tela Pessoas.

-- ─── Produção diária de refeições (kg): previsto, produzido e desperdiçado ─────────
-- Alimenta "Previsão de Demanda", "Distribuição de Refeições", produção e desperdício.

-- ─── Ajuste final: sem fins de semana e sem eventos futuros ─────────────────────────
-- (DAYOFWEEK: 1 = domingo, 7 = sábado). Assim os dados fazem sentido em qualquer dia da semana.
DELETE FROM logs_acesso        WHERE empresa_id = @emp AND (DAYOFWEEK(data_hora) IN (1, 7) OR data_hora > NOW());
DELETE FROM producao_refeicoes WHERE empresa_id = @emp AND DAYOFWEEK(data) IN (1, 7);

-- ─── Conferência rápida ──────────────────────────────────────────────────────────
SELECT 'funcionarios' AS tabela, COUNT(*) AS linhas FROM funcionarios WHERE empresa_id = @emp
UNION ALL SELECT 'credenciais_acesso', COUNT(*) FROM credenciais_acesso WHERE funcionario_id >= @f1
UNION ALL SELECT 'dispositivos_iot', COUNT(*) FROM dispositivos_iot WHERE empresa_id = @emp
UNION ALL SELECT 'logs_acesso', COUNT(*) FROM logs_acesso WHERE empresa_id = @emp
UNION ALL SELECT 'producao_refeicoes', COUNT(*) FROM producao_refeicoes WHERE empresa_id = @emp;
